using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Interop;using System.Windows.Media.Animation;using System.Windows.Threading;using Rhino;using EP=Eto.Drawing.PointF;
namespace RhinoContextAssist;
public partial class ContextAssistPopup:Window{readonly Action<ContextAction> execute;readonly Action dismiss;readonly ContextAssistSettings s;readonly DispatcherTimer timer;DateTime last;DateTime? hover,leave;bool expanded,drag;System.Windows.Point dragStart;double startL,startT;static PopupPositionMode? sessionCorner;
 internal ContextAssistPopup(Action<ContextAction> e,Action d,ContextAssistSettings settings){InitializeComponent();execute=e;dismiss=d;s=settings;timer=new DispatcherTimer(TimeSpan.FromMilliseconds(50),DispatcherPriority.Background,(_,_)=>Tick(),Dispatcher);SourceInitialized+=Init;Header.MouseLeftButtonDown+=DragDown;Header.MouseMove+=DragMove;Header.MouseLeftButtonUp+=(_,_)=>{drag=false;Header.ReleaseMouseCapture();};}
 internal void UpdateActions(SelectionContext c,IReadOnlyList<ContextAction>a){Pill.Content=$"{Icon(c.Kind)} {c.Caption} · {a.Count}";Title.Text=$"{Icon(c.Kind)} {c.Caption}";Primary.Children.Clear();MoreRoot.Children.Clear();var n=Math.Min(s.PrimaryCount,a.Count);foreach(var x in a.Take(n))Primary.Children.Add(Btn(x,false));var rest=a.Skip(n).GroupBy(x=>x.Category).ToList();if(rest.Count>0){var mb=Btn(new("more","⋯","Mehr", "","Weitere Aktionen"),false);mb.Click+=(_,_)=>More.IsOpen=!More.IsOpen;Primary.Children.Add(mb);More.PlacementTarget=mb;foreach(var g in rest){MoreRoot.Children.Add(new TextBlock{Text=g.Key,Foreground=System.Windows.Media.Brushes.Gray,Margin=new Thickness(8,7,4,2)});foreach(var x in g)MoreRoot.Children.Add(Btn(x,true));}}}
 Button Btn(ContextAction a,bool more){var b=new Button{Content=$"{a.Icon} {a.Label}",ToolTip=a.Hint,Style=(Style)FindResource(a.Destructive?"Danger":"B"),MinWidth=more?240:0,HorizontalContentAlignment=more?HorizontalAlignment.Left:HorizontalAlignment.Center};if(a.Id!="more")b.Click+=(_,_)=>execute(a);return b;}
 internal void ShowAt(SelectionContext c,PopupPositionMode mode){var p=Pos(c,mode);Left=p.X;Top=p.Y;last=DateTime.UtcNow;SetExpanded(s.UxMode==PopupUxMode.Direct);Opacity=s.IdleOpacity/100d;Show();Clamp();timer.Start();}
 EP Pos(SelectionContext c,PopupPositionMode mode){var v=RhinoDoc.ActiveDoc?.Views.ActiveView;var mouse=Eto.Forms.Mouse.Position;if(v==null)return mouse;var r=v.ScreenRectangle;var p=mouse;if(c.Anchor.IsValid){var q=v.ActiveViewport.WorldToClient(c.Anchor);p=new EP((float)(r.Left+q.X),(float)(r.Top+q.Y));}if(mode==PopupPositionMode.Mouse)return new(mouse.X+s.CursorOffsetPx,mouse.Y+s.CursorOffsetPx);if(mode==PopupPositionMode.Geometry)return new(p.X+s.CursorOffsetPx,p.Y+s.CursorOffsetPx);if(mode==PopupPositionMode.GeometryOffset){var dx=p.X-(r.Left+r.Width/2f);var dy=p.Y-(r.Top+r.Height/2f);var l=Math.Max(1,Math.Sqrt(dx*dx+dy*dy));return new(p.X+(float)(dx/l*120),p.Y+(float)(dy/l*120));}var m=s.CornerMarginPx;var corners=new Dictionary<PopupPositionMode,EP>{{PopupPositionMode.TopLeft,new(r.Left+m,r.Top+m)},{PopupPositionMode.TopRight,new(r.Right-m-420,r.Top+m)},{PopupPositionMode.BottomLeft,new(r.Left+m,r.Bottom-m-90)},{PopupPositionMode.BottomRight,new(r.Right-m-420,r.Bottom-m-90)}};if(mode!=PopupPositionMode.AutoViewportCorner)return corners[mode];var best=corners.OrderByDescending(x=>Dist(x.Value,p)).First();if(sessionCorner.HasValue&&corners.TryGetValue(sessionCorner.Value,out var old)&&Dist(old,p)>=Dist(best.Value,p)*.75)return old;sessionCorner=best.Key;return best.Value;}
 static double Dist(EP a,EP b){var x=a.X-b.X;var y=a.Y-b.Y;return x*x+y*y;}
 void Tick(){if(!IsVisible)return;var now=DateTime.UtcNow;var inside=IsMouseOver||(More.IsOpen&&More.IsMouseOver);if(inside){last=now;leave=null;hover??=now;Fade(s.ActiveOpacity/100d);if(s.UxMode==PopupUxMode.Compact&&!expanded&&(now-hover.Value).TotalMilliseconds>=s.HoverDelayMs)SetExpanded(true);}else{hover=null;Fade(s.IdleOpacity/100d);if(expanded&&s.UxMode==PopupUxMode.Compact){leave??=now;var d=More.IsOpen?s.MoreCollapseDelayMs:s.CollapseDelayMs;if((now-leave.Value).TotalMilliseconds>=d)SetExpanded(false);}if(s.AutoHideMs>0&&(now-last).TotalMilliseconds>=s.AutoHideMs)dismiss();}}
 void SetExpanded(bool x){expanded=x;Pill.Visibility=x?Visibility.Collapsed:Visibility.Visible;Expanded.Visibility=x?Visibility.Visible:Visibility.Collapsed;if(!x)More.IsOpen=false;Dispatcher.BeginInvoke(()=>{UpdateLayout();Clamp();});}void Pill_Click(object a,RoutedEventArgs b)=>SetExpanded(true);void Close_Click(object a,RoutedEventArgs b)=>dismiss();void Fade(double x)=>BeginAnimation(OpacityProperty,new DoubleAnimation(x,TimeSpan.FromMilliseconds(130)));void Clamp(){var w=SystemParameters.WorkArea;Left=Math.Clamp(Left,w.Left+20,Math.Max(w.Left+20,w.Right-ActualWidth-20));Top=Math.Clamp(Top,w.Top+20,Math.Max(w.Top+20,w.Bottom-ActualHeight-20));}
 void DragDown(object a,MouseButtonEventArgs e){drag=true;dragStart=e.GetPosition(null);startL=Left;startT=Top;Header.CaptureMouse();}void DragMove(object a,MouseEventArgs e){if(!drag)return;var p=e.GetPosition(null);Left=startL+p.X-dragStart.X;Top=startT+p.Y-dragStart.Y;}
 void Init(object? a,EventArgs e){var h=new WindowInteropHelper(this).Handle;SetWindowLongPtr(h,-8,RhinoApp.MainWindowHandle());}static string Icon(SelectionKind k)=>k is SelectionKind.Block?"◆":k is SelectionKind.Mesh?"△":k is SelectionKind.Curve or SelectionKind.ClosedPlanarCurve?"⌁":"⬒";
 [DllImport("user32.dll",EntryPoint="SetWindowLongPtrW")]static extern IntPtr SetWindowLongPtr(IntPtr h,int i,IntPtr n);
}
